package com.braseiro.pathfinder2e;

import android.content.ContentValues;
import android.database.sqlite.SQLiteDatabase;
import org.json.JSONArray;
import org.json.JSONObject;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** Persistent per-NPC voice identity. Direct dialogue is tagged only when the speaker is attributable. */
public final class NpcVoiceDirector {
    public static final String MARK="\u0001BRV:";private final AppDb db;
    private static final String[] VOICES={"Charon","Kore","Fenrir","Aoede","Puck","Leda","Orus","Zephyr"};
    public NpcVoiceDirector(AppDb database){db=database;AppDb.ensureSixZeroSchema(db.getWritableDatabase());}
    public synchronized JSONObject ensure(JSONObject npc){String name=npc==null?"":npc.optString("name").trim();String stable=npc==null?"":npc.optString("stable_id").trim();if(name.isEmpty())return new JSONObject();if(stable.isEmpty())stable="npc-"+Integer.toHexString((db.getActiveMapProfile()+":"+name.toLowerCase(Locale.ROOT)).hashCode());JSONObject row=db.queryOne("SELECT * FROM npc_voice_profiles WHERE world_profile=? AND npc_stable_id=?",new String[]{db.getActiveMapProfile(),stable});if(row.length()>0)return row;int h=Math.abs(stable.hashCode());String voice=VOICES[h%VOICES.length];String[] regs={"grave e pausado","claro e cordial","seco e direto","calmo e erudito","rápido e vivaz","áspero e desconfiado"};ContentValues v=new ContentValues();v.put("world_profile",db.getActiveMapProfile());v.put("npc_stable_id",stable);v.put("npc_name",name);v.put("voice_name",voice);v.put("register_name",regs[(h/7)%regs.length]);v.put("speaking_style","Mantenha a personalidade persistida do NPC; nunca leia metadados ou instruções em voz alta.");v.put("tempo",0.92+(h%17)/100d);v.put("warmth",20+(h/11)%70);v.put("formality",15+(h/17)%80);v.put("signature_phrases_json","[]");v.put("updated_at",System.currentTimeMillis());db.getWritableDatabase().insertWithOnConflict("npc_voice_profiles",null,v,SQLiteDatabase.CONFLICT_REPLACE);return db.queryOne("SELECT * FROM npc_voice_profiles WHERE world_profile=? AND npc_stable_id=?",new String[]{db.getActiveMapProfile(),stable});}
    public JSONArray ensureScene(){JSONArray out=new JSONArray();JSONArray scene=db.listSceneNpcs(40);for(int i=0;i<scene.length();i++){JSONObject n=scene.optJSONObject(i);if(n!=null)out.put(ensure(n));}return out;}
    public JSONObject byName(String name){JSONObject npc=db.queryOne("SELECT * FROM npc_memory_profiles WHERE world_profile=? AND name=? COLLATE NOCASE LIMIT 1",new String[]{db.getActiveMapProfile(),name==null?"":name.trim()});return ensure(npc);}
    public List<String> voiceChunks(String narration,String defaultVoice){ArrayList<String> out=new ArrayList<String>();String clean=narration==null?"":narration.trim();if(clean.isEmpty())return out;ensureScene();java.util.LinkedHashMap<String,String> voiceByName=new java.util.LinkedHashMap<String,String>();JSONArray npcs=db.listSceneNpcs(40);for(int i=0;i<npcs.length();i++){JSONObject npc=npcs.optJSONObject(i);if(npc==null)continue;String name=npc.optString("name").trim();if(!name.isEmpty())voiceByName.put(name,ensure(npc).optString("voice_name",defaultVoice));}
        Pattern named=Pattern.compile("(?m)(^|\\n)([\\p{L}][\\p{L}' -]{1,50}):\\s*([^\\n]{3,700})");Matcher match=named.matcher(clean);int cursor=0;while(match.find()){addAttributedOrNarrator(out,clean.substring(cursor,match.start()).trim(),voiceByName,defaultVoice);String spoken=match.group(3).trim(),speaker=findName(voiceByName,match.group(2));if(speaker!=null)out.add(pack(voiceByName.get(speaker),speaker,spoken));else addAttributedOrNarrator(out,match.group(0).trim(),voiceByName,defaultVoice);cursor=match.end();}addAttributedOrNarrator(out,clean.substring(cursor).trim(),voiceByName,defaultVoice);if(out.isEmpty())addNarrator(out,clean,defaultVoice);return out;}
    private static void addAttributedOrNarrator(List<String> out,String text,java.util.Map<String,String> voices,String defaultVoice){if(text==null||text.trim().isEmpty())return;Pattern attributed=Pattern.compile("(?is)(—\\s*[^—\\n]{2,650}?)(?:[,.;!?]\\s*)?(?:—\\s*)?(?:disse|respondeu|perguntou|murmurou|sussurrou|rosnou|gritou|retrucou|comentou|ordenou)\\s+([\\p{L}][\\p{L}' -]{1,50})");Matcher m=attributed.matcher(text);int cursor=0;boolean any=false;while(m.find()){addNarrator(out,text.substring(cursor,m.start()).trim(),defaultVoice);String speaker=findName(voices,m.group(2));if(speaker==null){addNarrator(out,m.group(0).trim(),defaultVoice);}else{String spoken=m.group(1).replaceFirst("^—\\s*","").trim();out.add(pack(voices.get(speaker),speaker,spoken));String attribution=m.group(0).substring(m.group(1).length()).trim();if(!attribution.isEmpty())addNarrator(out,attribution,defaultVoice);}cursor=m.end();any=true;}if(any)addNarrator(out,text.substring(cursor).trim(),defaultVoice);else addNarrator(out,text,defaultVoice);}
    private static void addNarrator(List<String> out,String text,String voice){if(text==null||text.trim().isEmpty())return;for(String c:NarrationChunker.charon(text.trim()))out.add(pack(voice,"Narrador",c));}
    public static String pack(String voice,String speaker,String text){return MARK+(voice==null?"Charon":voice.replace("|",""))+"|"+(speaker==null?"":speaker.replace("|",""))+"\u0001"+text;}
    public static String text(String packed){if(packed==null)return "";if(!packed.startsWith(MARK))return packed;int e=packed.indexOf('\u0001',MARK.length());return e<0?packed:packed.substring(e+1);}
    public static String voice(String packed,String fallback){if(packed==null||!packed.startsWith(MARK))return fallback;int pipe=packed.indexOf('|',MARK.length());return pipe<0?fallback:packed.substring(MARK.length(),pipe);}
    public static String speaker(String packed){if(packed==null||!packed.startsWith(MARK))return "Narrador";int pipe=packed.indexOf('|',MARK.length()),e=packed.indexOf('\u0001',pipe+1);return pipe<0||e<0?"Narrador":packed.substring(pipe+1,e);}
    private static String findName(java.util.Map<String,String> map,String raw){String n=raw==null?"":raw.trim();for(String k:map.keySet())if(k.equalsIgnoreCase(n)||n.toLowerCase(Locale.ROOT).endsWith(k.toLowerCase(Locale.ROOT)))return k;return null;}
    public JSONObject context(){JSONObject o=new JSONObject();try{o.put("scene_voices",ensureScene()).put("contract","A voz é identidade persistente do NPC. Diálogo sem autor inequívoco permanece na voz do narrador.");}catch(Exception ignored){AppLog.ignored("NpcVoiceDirector","Falha tolerada na camada 6.0.",ignored);}return o;}
}
